#include "drv_i2c_mpu6050.h"

#ifndef __AVR__
#include <stdint.h>
volatile uint8_t TWBR;
volatile uint8_t TWSR;
volatile uint8_t TWCR;
volatile uint8_t TWDR;
#else
#include <avr/io.h>
#endif

#ifndef TWINT
#define TWINT 7
#define TWSTA 5
#define TWSTO 4
#define TWEN  2
#endif

static uint8_t i2c_state = 0;
static uint8_t i2c_target_reg = 0;
static uint8_t i2c_data_buf[1] = {0};
static uint8_t i2c_is_read = 0;
static uint8_t i2c_busy = 0;
static uint8_t i2c_error = 0;

static uint8_t mpu_init_state = 0;
static uint8_t mpu_init_state_active = 0;
static uint8_t mpu_wait_timer = 0;

static void i2c_send_stop(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWINT) | (1 << TWSTO) | (1 << TWEN);
    i2c_busy = 0;
    i2c_state = 0;
}

static void i2c_start_tx(uint8_t reg, uint8_t data, uint8_t is_read) {
    i2c_target_reg = reg;
    i2c_data_buf[0] = data;
    i2c_is_read = is_read;
    i2c_busy = 1;
    i2c_error = 0;
    i2c_state = 1;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);
}

void drv_i2c_mpu6050_init(void) {
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWSR &= 0xFC;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWBR = 12;
    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
    TWCR = (1 << TWEN);

    i2c_state = 0;
    i2c_busy = 0;
    mpu_init_state = 0;
    mpu_init_state_active = 0;
    mpu_wait_timer = 0;
}

void drv_i2c_mpu6050_task(uint8_t dt_ms) {
    if (mpu_wait_timer > 0) {
        if (dt_ms >= mpu_wait_timer) {
            mpu_wait_timer = 0;
        } else {
            mpu_wait_timer -= dt_ms;
        }
        if (mpu_wait_timer > 0) return;
    }

    if (i2c_busy) {
        if (!(TWCR & (1 << TWINT))) return;

        // ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232
        uint8_t status = TWSR & 0xF8;

        switch (i2c_state) {
            case 1:
                if (status != 0x08) { i2c_error = 1; i2c_send_stop(); return; }
                TWDR = 0xD0;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                i2c_state = 2;
                break;
            case 2:
                if (status != 0x18) { i2c_error = 2; i2c_send_stop(); return; }
                TWDR = i2c_target_reg;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                i2c_state = 3;
                break;
            case 3:
                if (status != 0x28) { i2c_error = 3; i2c_send_stop(); return; }
                if (i2c_is_read) {
                    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                    TWCR = (1 << TWINT) | (1 << TWSTA) | (1 << TWEN);
                    i2c_state = 4;
                } else {
                    TWDR = i2c_data_buf[0];
                    // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                    TWCR = (1 << TWINT) | (1 << TWEN);
                    i2c_state = 7;
                }
                break;
            case 4:
                if (status != 0x10) { i2c_error = 4; i2c_send_stop(); return; }
                TWDR = 0xD1;
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                i2c_state = 5;
                break;
            case 5:
                if (status != 0x40) { i2c_error = 5; i2c_send_stop(); return; }
                // ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224
                TWCR = (1 << TWINT) | (1 << TWEN);
                i2c_state = 6;
                break;
            case 6:
                if (status != 0x58) { i2c_error = 6; i2c_send_stop(); return; }
                i2c_data_buf[0] = TWDR;
                i2c_send_stop();
                break;
            case 7:
                if (status != 0x28) { i2c_error = 7; i2c_send_stop(); return; }
                i2c_send_stop();
                break;
            default:
                i2c_error = 8;
                i2c_send_stop();
                break;
        }
        return;
    }

    if (!i2c_busy && mpu_init_state < 6) {
        if (i2c_error) {
            mpu_init_state_active = 0;
            i2c_error = 0;
        } else {
            if (mpu_init_state_active) {
                mpu_init_state++;
                mpu_init_state_active = 0;
            }
        }

        if (!mpu_init_state_active && mpu_init_state < 6) {
            switch (mpu_init_state) {
                case 0:
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    i2c_start_tx(0x75, 0, 1);
                    mpu_init_state_active = 1;
                    break;
                case 1:
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    if (i2c_data_buf[0] == 0x68) {
                        // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                        i2c_start_tx(0x6B, 0x80, 0);
                        mpu_init_state_active = 1;
                    } else {
                        mpu_init_state = 0xFF;
                    }
                    break;
                case 2:
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    i2c_start_tx(0x6B, 0x01, 0);
                    mpu_init_state_active = 1;
                    break;
                case 3:
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    mpu_wait_timer = 100;
                    mpu_init_state_active = 1;
                    break;
                case 4:
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    i2c_start_tx(0x1A, 0x03, 0);
                    mpu_init_state_active = 1;
                    break;
                case 5:
                    // ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45
                    i2c_start_tx(0x19, 0x09, 0);
                    mpu_init_state_active = 1;
                    break;
            }
        }
    }
}

uint8_t drv_i2c_mpu6050_is_ready(void) {
    return (mpu_init_state == 6);
}
