            cls.TWBR = ctypes.c_uint8.in_dll(cls.lib, "TWBR")
            cls.TWSR = ctypes.c_uint8.in_dll(cls.lib, "TWSR")
            cls.TWCR = ctypes.c_uint8.in_dll(cls.lib, "TWCR")
            cls.TWDR = ctypes.c_uint8.in_dll(cls.lib, "TWDR")
        except Exception as e:
            print(f"Compilation skipped/failed: {e}")

    def test_citations(self):
        with open("src/drv_i2c_mpu6050.c", "r") as f:
            content = f.read()
        self.assertIn("ref: ds-021, ATmega328P datasheet rev. DS40002061B, tr.222-224", content)
        self.assertIn("ref: ds-022, ATmega328P datasheet rev. DS40002061B, tr.228-232", content)
        self.assertIn("ref: ds-031, MPU-6000/MPU-6050 Register Map rev. 4.2, tr.40-45", content)

    def test_init(self):
        if not self.lib:
            self.skipTest("C library not compiled")
        self.lib.drv_i2c_mpu6050_init()
        self.assertEqual(self.TWBR.value, 12)
        self.assertEqual(self.TWSR.value & 0x03, 0)
        self.assertTrue(self.TWCR.value & (1 << 2))

    def test_state_machine_non_blocking(self):
        if not self.lib:
            self.skipTest("C library not compiled")
        self.lib.drv_i2c_mpu6050_init()

        # Start WHO_AM_I transaction
        self.lib.drv_i2c_mpu6050_task(10)
        self.assertTrue(self.TWCR.value & (1 << 5)) # TWSTA

        # Simulate START sent
        self.TWCR.value |= (1 << 7)
        self.TWSR.value = 0x08
        self.lib.drv_i2c_mpu6050_task(10)
        self.assertEqual(self.TWDR.value, 0xD0)

        # Simulate SLA+W ACK
        self.TWCR.value |= (1 << 7)
        self.TWSR.value = 0x18
        self.lib.drv_i2c_mpu6050_task(10)
        self.assertEqual(self.TWDR.value, 0x75)

        # Simulate Reg ACK
        self.TWCR.value |= (1 << 7)
        self.TWSR.value = 0x28
        self.lib.drv_i2c_mpu6050_task(10)
        self.assertTrue(self.TWCR.value & (1 << 5)) # REP_START

        # Simulate REP_START sent
        self.TWCR.value |= (1 << 7)
        self.TWSR.value = 0x10
        self.lib.drv_i2c_mpu6050_task(10)
        self.assertEqual(self.TWDR.value, 0xD1)

        # Simulate SLA+R ACK
        self.TWCR.value |= (1 << 7)
        self.TWSR.value = 0x40
        self.lib.drv_i2c_mpu6050_task(10)

        # Simulate Data RX NACK
        self.TWCR.value |= (1 << 7)
        self.TWSR.value = 0x58
        self.TWDR.value = 0x68 # Expected WHO_AM_I
        self.lib.drv_i2c_mpu6050_task(10)

        # Check STOP condition
        self.assertTrue(self.TWCR.value & (1 << 4)) # TWSTO

        # Verify state machine advanced
        self.lib.drv_i2c_mpu6050_task(10)
        self.assertTrue(self.TWCR.value & (1 << 5)) # Next state starts (Reset)

if __name__ == "__main__":
    unittest.main()
