#include <stdint.h>

/* Fixed point scaling factor to avoid floating point arithmetic */
#define PID_SCALE_FACTOR 1000

typedef struct {
    int32_t kp;
    int32_t ki;
    int32_t kd;
    int32_t integral;
    int32_t prev_error;
    int32_t out_min;
    int32_t out_max;
    int32_t integral_min;
    int32_t integral_max;
} pid_context_t;

void pid_controller_init(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd, int32_t out_min, int32_t out_max);
int32_t pid_controller_update(pid_context_t *ctx, int32_t setpoint, int32_t measured, uint8_t dt_ms);
