#include "pid_controller.h"
#include "drv_i2c_mpu6050.h"

void pid_controller_init(pid_context_t *ctx, int32_t kp, int32_t ki, int32_t kd, int32_t out_min, int32_t out_max) {
    if (!ctx) {
        return;
    }

    ctx->kp = kp;
    ctx->ki = ki;
    ctx->kd = kd;
    ctx->integral = 0;
    ctx->prev_error = 0;
    ctx->out_min = out_min;
    ctx->out_max = out_max;

    /* Anti-windup limits for integral term */
    ctx->integral_min = out_min * PID_SCALE_FACTOR;
    ctx->integral_max = out_max * PID_SCALE_FACTOR;
}

int32_t pid_controller_update(pid_context_t *ctx, int32_t setpoint, int32_t measured, uint8_t dt_ms) {
    if (!ctx || dt_ms == 0) {
        return 0;
    }

    int32_t error = setpoint - measured;

    /* Proportional term */
    int32_t p_term = ctx->kp * error;

    /* Integral term */
    ctx->integral += ctx->ki * error * (int32_t)dt_ms;

    /* Anti-windup clamping */
    if (ctx->integral > ctx->integral_max) {
        ctx->integral = ctx->integral_max;
    } else if (ctx->integral < ctx->integral_min) {
        ctx->integral = ctx->integral_min;
    }

    /* Derivative term */
    int32_t d_term = ctx->kd * (error - ctx->prev_error) / (int32_t)dt_ms;
    ctx->prev_error = error;

    /* Total output calculation */
    int32_t output = (p_term + ctx->integral + d_term) / PID_SCALE_FACTOR;

    /* Output clamping */
    if (output > ctx->out_max) {
        output = ctx->out_max;
    } else if (output < ctx->out_min) {
        output = ctx->out_min;
    }

    return output;
}

