import ctypes
import os
import subprocess
import pytest

@pytest.fixture(scope="session")
def pid_lib(tmp_path_factory):
    src_path = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', 'src', 'pid_controller.c'))

    # Create a dummy drv_i2c_mpu6050.h for compilation to satisfy dependencies
    inc_dir = tmp_path_factory.mktemp("include")
    with open(os.path.join(inc_dir, "drv_i2c_mpu6050.h"), "w") as f:
        f.write("#ifndef DRV_I2C_MPU6050_H\n#define DRV_I2C_MPU6050_H\n#include <stdint.h>\nvoid drv_i2c_mpu6050_init(void);\nvoid drv_i2c_mpu6050_task(uint8_t dt_ms);\nuint8_t drv_i2c_mpu6050_is_ready(void);\n#endif\n")

    src_inc_dir = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', 'src'))
    out_lib = tmp_path_factory.mktemp("lib") / "libpid.so"

    compile_cmd = [
        "gcc", "-shared", "-fPIC", "-O2",
        f"-I{inc_dir}", f"-I{src_inc_dir}",
        src_path, "-o", str(out_lib)
    ]

    subprocess.run(compile_cmd, check=True)
    lib = ctypes.CDLL(str(out_lib))

    class PIDContext(ctypes.Structure):
        _fields_ = [
            ("kp", ctypes.c_int32),
            ("ki", ctypes.c_int32),
            ("kd", ctypes.c_int32),
            ("integral", ctypes.c_int32),
            ("prev_error", ctypes.c_int32),
            ("out_min", ctypes.c_int32),
            ("out_max", ctypes.c_int32),
            ("integral_min", ctypes.c_int32),
            ("integral_max", ctypes.c_int32),
        ]

    lib.pid_controller_init.argtypes = [ctypes.POINTER(PIDContext), ctypes.c_int32, ctypes.c_int32, ctypes.c_int32, ctypes.c_int32, ctypes.c_int32]
    lib.pid_controller_update.argtypes = [ctypes.POINTER(PIDContext), ctypes.c_int32, ctypes.c_int32, ctypes.c_uint8]
    lib.pid_controller_update.restype = ctypes.c_int32

    lib.PIDContext = PIDContext
    return lib

def test_pid_initialization(pid_lib):
    ctx = pid_lib.PIDContext()
    pid_lib.pid_controller_init(ctypes.byref(ctx), 1000, 500, 100, -255, 255)

    assert ctx.kp == 1000
    assert ctx.ki == 500
    assert ctx.kd == 100
    assert ctx.integral == 0
    assert ctx.prev_error == 0
    assert ctx.out_min == -255
    assert ctx.out_max == 255
    assert ctx.integral_min == -255000
    assert ctx.integral_max == 255000

def test_pid_update_proportional(pid_lib):
    ctx = pid_lib.PIDContext()
    # kp=1000 (equivalent to 1.0 with scale factor 1000), ki=0, kd=0
    pid_lib.pid_controller_init(ctypes.byref(ctx), 1000, 0, 0, -255, 255)

    # setpoint = 100, measured = 50 -> error = 50
    # P = 1000 * 50 = 50000 -> output = 50000 / 1000 = 50
    output = pid_lib.pid_controller_update(ctypes.byref(ctx), 100, 50, 10)
    assert output == 50

def test_pid_update_clamping(pid_lib):
    ctx = pid_lib.PIDContext()
    # kp=10000 (equivalent to 10.0), ki=0, kd=0
    pid_lib.pid_controller_init(ctypes.byref(ctx), 10000, 0, 0, -255, 255)

    # error = 100 -> P = 1000000 -> output = 1000 -> clamped to 255
    output = pid_lib.pid_controller_update(ctypes.byref(ctx), 100, 0, 10)
    assert output == 255

def test_pid_update_integral_anti_windup(pid_lib):
    ctx = pid_lib.PIDContext()
    # kp=0, ki=1000 (1.0), kd=0
    pid_lib.pid_controller_init(ctypes.byref(ctx), 0, 1000, 0, -100, 100)

    # error = 50, dt = 10ms -> integral += 1000 * 50 * 10 = 500000
    # max integral = 100 * 1000 = 100000
    # integral should clamp to 100000
    output = pid_lib.pid_controller_update(ctypes.byref(ctx), 50, 0, 10)
    assert ctx.integral == 100000
    assert output == 100
